-- Points and desk decoration purchases. Every find added to the collection earns 1 point (deleting it later doesn't
-- take the point back); points buy decorations, and spent points stay spent. Free decorations are owned by everyone.
-- Requires the earlier migrations to have been run first. Safe to run more than once.
-- After running this, run supabase/desk_decor_prices.sql (generated by `npm run import-desk-decor`).
--
-- Users can only read their points and purchases; they change only through the logs trigger and purchase_desk_decor
-- below, so points can't be edited from the browser.

-- Price of every decoration in src/data/deskDecorCatalog.json (0 = free). Filled by supabase/desk_decor_prices.sql.
create table if not exists public.desk_decor_prices (
  decor_id text primary key check (char_length(decor_id) between 1 and 100),
  price integer not null check (price >= 0)
);

-- One row per user who has earned or spent points (no row = 0 points).
create table if not exists public.user_points (
  user_id uuid primary key references auth.users (id) on delete cascade,
  earned integer not null default 0 check (earned >= 0),
  spent integer not null default 0 check (spent >= 0 and spent <= earned)
);

-- Decorations each user has bought, with the price paid.
create table if not exists public.user_decor (
  user_id uuid not null references auth.users (id) on delete cascade,
  decor_id text not null check (char_length(decor_id) between 1 and 100),
  price integer not null check (price >= 0),
  purchased_at timestamptz not null default now(),
  primary key (user_id, decor_id)
);

alter table public.desk_decor_prices enable row level security;
alter table public.user_points enable row level security;
alter table public.user_decor enable row level security;

revoke all on public.desk_decor_prices from anon, authenticated;
revoke all on public.user_points from anon, authenticated;
revoke all on public.user_decor from anon, authenticated;
grant select on public.desk_decor_prices to authenticated;
grant select on public.user_points to authenticated;
grant select on public.user_decor to authenticated;

drop policy if exists "Signed-in users can read decoration prices" on public.desk_decor_prices;
create policy "Signed-in users can read decoration prices"
  on public.desk_decor_prices for select to authenticated
  using (true);

drop policy if exists "Users can read their own points" on public.user_points;
create policy "Users can read their own points"
  on public.user_points for select to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists "Users can read their own decorations" on public.user_decor;
create policy "Users can read their own decorations"
  on public.user_decor for select to authenticated
  using ((select auth.uid()) = user_id);

-- Each new find earns a point.
create or replace function public.award_log_point()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.user_points (user_id, earned) values (new.user_id, 1)
  on conflict (user_id) do update set earned = public.user_points.earned + 1;
  return new;
end;
$$;

revoke execute on function public.award_log_point() from public, anon, authenticated;

drop trigger if exists logs_award_point on public.logs;
create trigger logs_award_point
  after insert on public.logs
  for each row execute function public.award_log_point();

-- Finds logged before points existed count too (only for users who don't have points yet, so re-running is safe).
insert into public.user_points (user_id, earned)
select user_id, count(*) from public.logs group by user_id
on conflict (user_id) do nothing;

-- Buys a decoration for the signed-in user and returns their points afterwards ({ "earned": n, "spent": n }). Fails
-- with 'not enough points' or 'unknown decoration'. Buying something already owned (or free) costs nothing.
drop function if exists public.purchase_desk_decor(text);
create function public.purchase_desk_decor(decor text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  item_price integer;
  points public.user_points;
begin
  if uid is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;

  select price into item_price from public.desk_decor_prices where decor_id = decor;
  if item_price is null then
    raise exception 'unknown decoration' using errcode = 'P0002';
  end if;

  -- Lock the user's points so two purchases at once can't both spend the same points.
  insert into public.user_points (user_id) values (uid) on conflict (user_id) do nothing;
  select * into points from public.user_points where user_id = uid for update;

  if item_price > 0 and not exists (select 1 from public.user_decor where user_id = uid and decor_id = decor) then
    if points.earned - points.spent < item_price then
      raise exception 'not enough points' using errcode = 'P0001';
    end if;
    insert into public.user_decor (user_id, decor_id, price) values (uid, decor, item_price);
    update public.user_points set spent = spent + item_price where user_id = uid returning * into points;
  end if;
  return jsonb_build_object('earned', points.earned, 'spent', points.spent);
end;
$$;

revoke execute on function public.purchase_desk_decor(text) from public, anon;
grant execute on function public.purchase_desk_decor(text) to authenticated;

-- A saved desk may only hold decorations that are free or that the user owns.
create or replace function public.check_desk_setup()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if jsonb_typeof(new.desk_setup -> 'decorations') = 'array' and exists (
    select 1
    from jsonb_array_elements(new.desk_setup -> 'decorations') as placed
    where not exists (select 1 from public.desk_decor_prices p where p.decor_id = placed ->> 'id' and p.price = 0)
      and not exists (select 1 from public.user_decor d where d.user_id = new.id and d.decor_id = placed ->> 'id')
  ) then
    raise exception 'desk has decorations you don''t own' using errcode = '42501';
  end if;
  return new;
end;
$$;

revoke execute on function public.check_desk_setup() from public, anon, authenticated;

drop trigger if exists profiles_check_desk_setup on public.profiles;
create trigger profiles_check_desk_setup
  before insert or update of desk_setup on public.profiles
  for each row execute function public.check_desk_setup();
